def bridge_check(bridge,cfos):
    sums=[sum(D(str(v[i])) for v in bridge.values()) for i in range(2)]
    residual=[sums[i]-D(str(cfos[i])) for i in range(2)]
    assert residual==[D(0),D(0)],residual
    return {'sums_CNY':[str(v) for v in sums],'residual_CNY':[str(v) for v in residual],'contribution_to_change_CNY':{k:str(D(str(v[0]))-D(str(v[1]))) for k,v in bridge.items()}}
